/** Alto (px) de un logo de 56 de alto en la imagen; los más altos (dos líneas) crecen en proporción. */
const ALTO_BASE = 26;
/** Ancho máximo (px): los logos muy alargados (El Diario Vasco) se reducen hasta caber. */
const ANCHO_MAX = 240;

/**
 * Markup <svg> del logo con width/height explícitos (html2canvas y Safari los necesitan),
 * o null si el medio no tiene logo.
 */
export function logoDelMedio(idMedio) {
  const logo = LOGOS_MEDIOS[idMedio];
  if (!logo) return null;
  let alto = ALTO_BASE * (logo.alto / 56);
  let ancho = alto * (logo.ancho / logo.alto);
  if (ancho > ANCHO_MAX) {
    alto *= ANCHO_MAX / ancho;
    ancho = ANCHO_MAX;
  }
  const r = (n) => Math.round(n * 10) / 10;
  // También en style: las hojas de estilo del CMS estiran los <svg> y ganan a los atributos width/height.
  const w = r(ancho);
  const h = r(alto);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${logo.ancho} ${logo.alto}" width="${w}" height="${h}" style="width:${w}px;height:${h}px;max-width:none" fill="none" role="img"><path fill="#202020" d="${logo.d}"/></svg>`;
}
